css:
body { font-family: system-ui, sans-serif; margin: 0; background: #fff8ef; }
header, aside, footer { background: #c0392b; color: #fff; padding: 0.75rem; }
aside { background: #8e2a20; }
main { padding: 0.5rem; }
.card { background: #fff; border: 2px solid #c0392b; border-radius: 12px; padding: 0.75rem; }

/* Your CSS below:
   1. .cards: as many columns as fit, each at least 140px (auto-fit + minmax), gap 1rem
   2. .page: a grid with areas "header header" / "main aside" / "footer footer",
      columns 1fr 160px, and give header/main/aside/footer their grid-area
   3. Under 600px wide: one column, with areas header / main / aside / footer */
.cards {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
  gap: 1rem;
}
.page {
  display: grid;
  grid-template-columns: 1fr 160px;
  grid-template-areas:
    "header header"
    "main aside"
    "footer footer";
}
header { grid-area: header; }
main { grid-area: main; }
aside { grid-area: aside; }
footer { grid-area: footer; }
@media (max-width: 600px) {
  .page {
    grid-template-columns: 1fr;
    grid-template-areas: "header" "main" "aside" "footer";
  }
}
